  if (sortedDnaSequences.isEmpty || prefix.isEmpty) return [];
  int n = sortedDnaSequences.length;
  int low = 0;
  int high = n;
  while (low < high) {
    int mid = low + (high - low) ~/ 2;
    if (sortedDnaSequences[mid].compareTo(prefix) < 0) {
      low = mid + 1;
    } else {
      high = mid;
    }
  }
  int start = low;
  low = 0;
  high = n;
  while (low < high) {
    int mid = low + (high - low) ~/ 2;
