      low = mid + 1;
    } else {
      high = mid;
    }
  }
  int end = low;
  low = start;
  while (low < end && !sortedDnaSequences[low].startsWith(prefix)) {
    low++;
  }
  return sortedDnaSequences.sublist(low, end);
}

