  List<String> wordDict4 = ["cats", "dog", "sand", "and", "cat"];

  bool wordBreak(String s, List<String> wordDict) {

    Set<String> wordSet = wordDict.toSet();

    List<bool> dp = List.filled(s.length + 1, false);
    dp[0] = true; 

    for (int i = 1; i <= s.length; i++) {

      for (int j = 0; j < i; j++) {

        if (dp[j] && wordSet.contains(s.substring(j, i))) {
          dp[i] = true;
          break; 
        }
      }
    }

    return dp[s.length];
  }

  List<String> wordBreakII(String s, List<String> wordDict) {
    Set<String> wordSet = wordDict.toSet();
    Map<String, List<String>> memo = {};

    List<String> backtrack(String remaining) {

      if (memo.containsKey(remaining)) {
        return memo[remaining]!;
      }

      List<String> result = [];

      if (remaining.isEmpty) {
        result.add("");
        return result;
      }

      for (int i = 1; i <= remaining.length; i++) {
        String prefix = remaining.substring(0, i);

        if (wordSet.contains(prefix)) {
          String suffix = remaining.substring(i);
          List<String> suffixWays = backtrack(suffix);

          for (String way in suffixWays) {
            if (way.isEmpty) {
              result.add(prefix);
            } else {
              result.add("$prefix $way");
            }
          }
        }
      }

      memo[remaining] = result;
      return result;
    }

    return backtrack(s);
  }

  print("=== Word Break (Can Segment?) ===");
  print("String: '$s1', Dictionary: $wordDict1");
  print("Can segment: ${wordBreak(s1, wordDict1)}");
  print("");

