  List<String> segmentations = wordBreakII(s5, wordDict5);
  print("String: '$s5', Dictionary: $wordDict5");
  print("All possible segmentations:");
  for (String seg in segmentations) {
    print("  - $seg");
  }
  print("");

  String s6 = "pineapplepenapple";
