  int minWordBreaks(String s, List<String> wordDict) {
    Set<String> wordSet = wordDict.toSet();
    int n = s.length;

    List<int> dp = List.filled(n + 1, n + 1); 
    dp[0] = 0; 

    for (int i = 1; i <= n; i++) {
      for (int j = 0; j < i; j++) {
        if (dp[j] != n + 1 && wordSet.contains(s.substring(j, i))) {
          dp[i] = dp[i] < dp[j] + 1 ? dp[i] : dp[j] + 1;
        }
      }
    }

    return dp[n] == n + 1 ? -1 : dp[n];
  }

  print("=== Minimum Word Breaks ===");
  print("String: '$s1', Dictionary: $wordDict1");
  int minBreaks = minWordBreaks(s1, wordDict1);
