  Map<String, int> totals = {};
  List<int> scaleStack = [1];
  List<Map<String, int>> totalHistory = [];
  List<List<int>> scaleHistory = [];

  for (String op in operations) {
    if (op == 'UNDO') {
      if (totalHistory.isNotEmpty) {
        totals = totalHistory.removeLast();
        scaleStack = scaleHistory.removeLast();
      }
      continue;
    }

    totalHistory.add(Map<String, int>.from(totals));
