    } else if (parts[0] == 'END') {
      if (scaleStack.length > 1) {
        scaleStack.removeLast();
      }
    } else if (parts[0] == 'ADD') {
      String ingredient = parts[1];
      int amount = int.parse(parts[2]) * scaleStack.last;
      totals[ingredient] = (totals[ingredient] ?? 0) + amount;
    }
  }

  List<String> result = [];
  List<String> keys = totals.keys.toList()..sort();

  for (String key in keys) {
    result.add('$key=${totals[key]}');
  }

  return result;
}

