void fn0() {

  String text = "HERE IS A SIMPLE EXAMPLE";
  String pattern = "EXAMPLE";

  List<int> boyerMooreSearch(String text, String pattern) {
    int n = text.length;
    int m = pattern.length;
    if (m == 0 || n == 0 || m > n) return [];

    const int ALPHABET_SIZE = 256;
    List<int> badChar = List.filled(ALPHABET_SIZE, -1);
    for (int i = 0; i < m; i++) {
      badChar[pattern.codeUnitAt(i)] = i;
    }

    List<int> result = [];
    int s = 0; 

    while (s <= (n - m)) {
      int j = m - 1;

      while (j >= 0 && pattern[j] == text[s + j]) {
        j--;
      }

      if (j < 0) {
        result.add(s);

        s += (s + m < n)
            ? m - badChar[text.codeUnitAt(s + m)]
            : 1;
      } else {
        int badCharIdx = text.codeUnitAt(s + j);
        s += (j - badChar[badCharIdx]).clamp(1, m);
      }
    }
    return result;
  }

  List<int> positions = boyerMooreSearch(text, pattern);

  if (positions.isEmpty) {
    print("Pattern not found.");
  } else {
    print("Pattern found at positions: ${positions.join(', ')}");
  }
}

