    'W': ['B', 'A', 'D', 'C'],
    'X': ['C', 'B', 'A', 'D'],
    'Y': ['A', 'C', 'B', 'D'],
    'Z': ['A', 'B', 'C', 'D'],
  };

  final womenRank = <String, Map<String, int>>{};
  for (final w in women) {
    final ranking = <String, int>{};
    final prefs = womenPrefs[w]!;
    for (var i = 0; i < prefs.length; i++) {
      ranking[prefs[i]] = i;          
    }
    womenRank[w] = ranking;
  }

  final engagedWomen = <String, String>{};          
  final engagedMen   = <String, String>{};          
  final freeMen      = List<String>.of(men);        
  final nextIndex    = {for (var m in men) m: 0};   

  while (freeMen.isNotEmpty) {
    final man   = freeMen.removeAt(0);
    final prefs = menPrefs[man]!;
    final i     = nextIndex[man]!;
    final woman = prefs[i];               
    nextIndex[man] = i + 1;               

    if (!engagedWomen.containsKey(woman)) {

      engagedWomen[woman] = man;
      engagedMen[man]     = woman;
    } else {

      final currentFiance = engagedWomen[woman]!;
      final rank          = womenRank[woman]!;
      if (rank[man]! < rank[currentFiance]!) {

        engagedWomen[woman] = man;
        engagedMen
          ..remove(currentFiance)
          ..[man] = woman;
        freeMen.add(currentFiance);       
      } else {

        freeMen.add(man);
      }
    }
  }

  print('Stable matches:');
  for (final man in men) {
    print('$man → ${engagedMen[man]}');
  }
}

