@pragma('vm:never-inline')
@pragma('vm:entry-point')
int fn0(List<String> grid) {
  if (grid.isEmpty) return 0;
  int n = grid.length;
  List<int> solve(int r, int c, int size) {
    int ones = 0;
    for (int i = r; i < r + size; i++) {
      for (int j = c; j < c + size; j++) {
        if (grid[i][j] == '1') ones++;
      }
    }
    if (size < 2 || size % 2 != 0) {
      return [ones, ones];
    }
    int half = size ~/ 2;
    List<int> tl = solve(r, c, half);
    List<int> tr = solve(r, c + half, half);
    List<int> bl = solve(r + half, c, half);
    List<int> br = solve(r + half, c + half, half);
    int splitValue = tl[0] + tr[0] + bl[0] + br[0];
    int uniformCount = 0;
    int halfArea = half * half;
    if (tl[1] == 0 || tl[1] == halfArea) uniformCount++;
    if (tr[1] == 0 || tr[1] == halfArea) uniformCount++;
    if (bl[1] == 0 || bl[1] == halfArea) uniformCount++;
    if (br[1] == 0 || br[1] == halfArea) uniformCount++;
    splitValue += uniformCount * half;
    return [splitValue > ones ? splitValue : ones, ones];
  }
  return solve(0, 0, n)[0];
}

