int fn0(List<int> availableDays, int minGap, int maxGap) {
  if (availableDays.isEmpty) {
    return 0;
  }

  final int n = availableDays.length;
  final List<int> dpLen = List.filled(n, 1);
  final List<int> dpSum = List.filled(n, 0);

  for (int i = 0; i < n; i++) {
    dpSum[i] = availableDays[i];
    int bestLen = 1;
    int bestSum = availableDays[i];

    for (int j = i - 1; j >= 0; j--) {
      final int diff = availableDays[i] - availableDays[j];
      if (diff > maxGap) {
        break;
      }
      if (diff >= minGap) {
        final int candLen = dpLen[j] + 1;
        final int candSum = dpSum[j] + availableDays[i];
        if (candLen > bestLen || (candLen == bestLen && candSum > bestSum)) {
          bestLen = candLen;
          bestSum = candSum;
        }
      }
    }
    dpLen[i] = bestLen;
    dpSum[i] = bestSum;
  }

  int maxLen = 0;
  int maxSum = 0;
  for (int i = 0; i < n; i++) {
    if (dpLen[i] > maxLen) {
      maxLen = dpLen[i];
      maxSum = dpSum[i];
    } else if (dpLen[i] == maxLen && dpSum[i] > maxSum) {
      maxSum = dpSum[i];
    }
  }

  return maxSum;
}

