  final cellPattern = RegExp(r'^([WDM])(\d)$');
  int total = 0;
  final rows = grid.split('|');
  for (final row in rows) {
    if (row.isEmpty) continue;
    final cells = row.split(',');
    int rowSum = 0;
    bool valid = true;
    for (final cell in cells) {
      final m = cellPattern.firstMatch(cell);
      if (m == null) {
        valid = false;
        break;
      }
      final type = m.group(1)!;
      final digit = int.parse(m.group(2)!);
      if (type == 'W') {
        rowSum += digit * 2;
      } else if (type == 'M') {
        rowSum += digit * 3;
      } else {
        rowSum -= digit;
      }
    }
    if (valid) total += rowSum;
  }
  return total;
}

