int fn0(List<int> signals, List<int> binBoundaries, int binIndex, int k) {

  if (binBoundaries.length < 2) return -1;
  if (binIndex < 0 || binIndex >= binBoundaries.length - 1) return -1;

  int binLow = binBoundaries[binIndex];
  int binHigh = binBoundaries[binIndex + 1] - 1; 

  if (binLow > binHigh) return -1; 

  int countInBin = 0;
  for (int s in signals) {
    if (s >= binLow && s <= binHigh) countInBin++;
  }

  if (k <= 0 || k > countInBin) return -1;

  int low = binLow;
  int high = binHigh;
  while (low < high) {

    int mid = low + ((high - low + 1) >> 1);
    int count = 0;
    for (int s in signals) {
      if (s >= mid && s <= binHigh) count++;
    }
    if (count >= k) {
      low = mid; 
    } else {
      high = mid - 1; 
    }
  }
  return low;
}

