List<int> fn0(List<String> rows) {
  if (rows.isEmpty) return [];

  Set<String> filled = {};
  for (int r = 0; r < rows.length; r++) {
    for (int c = 0; c < rows[r].length; c++) {
      if (rows[r][c] == '#') filled.add('$r,$c');
    }
  }
  if (filled.isEmpty) return [];

  List<List<List<int>>> components = [];
  Set<String> visited = {};
  List<List<int>> dirs = [[-1, 0], [1, 0], [0, -1], [0, 1]];

  for (var key in filled) {
    if (visited.contains(key)) continue;
    List<List<int>> comp = [];
    List<String> queue = [key];
    visited.add(key);
    while (queue.isNotEmpty) {
      String cur = queue.removeAt(0);
      var p = cur.split(',');
      int cr = int.parse(p[0]), cc = int.parse(p[1]);
      comp.add([cr, cc]);
      for (var d in dirs) {
        int nr = cr + d[0], nc = cc + d[1];
        String nk = '$nr,$nc';
        if (filled.contains(nk) && !visited.contains(nk)) {
          visited.add(nk);
          queue.add(nk);
        }
      }
    }
    components.add(comp);
  }

  if (components.length < 2) return [];

  List<int> result = [];
  for (int i = 0; i < components.length; i++) {
    for (int j = i + 1; j < components.length; j++) {
      int best = 0x7FFFFFFF;
      for (var a in components[i]) {
        for (var b in components[j]) {
          int d = (a[0] - b[0]).abs() + (a[1] - b[1]).abs();
          if (d < best) best = d;
        }
      }
      result.add(best);
    }
  }
  result.sort();
  return result;
}

