List<int> fn0(List<int> targets, int startTemp, int maxStep) {
  List<int> best = <int>[];
  int bestCost = -1;

  void search(int index, int currentTemp, List<int> path, int cost) {
    if (index == targets.length) {
      if (bestCost == -1 || cost < bestCost) {
        bestCost = cost;
        best = List<int>.from(path);
      }
      return;
    }

    int low = currentTemp - maxStep;
    int high = currentTemp + maxStep;

    for (int next = low; next <= high; next++) {
      int nextCost = cost + (targets[index] - next).abs();

      if (bestCost != -1 && nextCost > bestCost) {
        continue;
      }

      path.add(next);
      search(index + 1, next, path, nextCost);
      path.removeLast();
    }
  }

  search(0, startTemp, <int>[], 0);
  return best;
}

