class Quaternion {
  final double w, x, y, z;

  const Quaternion(this.w, this.x, this.y, this.z);

  Quaternion operator +(Quaternion other) =>
      Quaternion(w + other.w, x + other.x, y + other.y, z + other.z);

  Quaternion operator -(Quaternion other) =>
      Quaternion(w - other.w, x - other.x, y - other.y, z - other.z);

  Quaternion operator *(dynamic other) {
    if (other is double || other is int) {
      return Quaternion(w * other, x * other, y * other, z * other);
    } else if (other is Quaternion) {

      return Quaternion(
        w * other.w - x * other.x - y * other.y - z * other.z,
        w * other.x + x * other.w + y * other.z - z * other.y,
        w * other.y - x * other.z + y * other.w + z * other.x,
        w * other.z + x * other.y - y * other.x + z * other.w,
      );
    } else {
      throw ArgumentError('Unsupported operand type');
    }
  }

  double norm() => sqrt(w * w + x * x + y * y + z * z);

  Quaternion normalized() {
    var n = norm();
    if (n == 0) throw StateError('Cannot normalize zero quaternion');
    return Quaternion(w / n, x / n, y / n, z / n);
  }

  Quaternion conjugate() => Quaternion(w, -x, -y, -z);

  Quaternion inverse() {
    var n2 = w * w + x * x + y * y + z * z;
    if (n2 == 0) throw StateError('Cannot invert zero quaternion');
    var conj = conjugate();
    return Quaternion(conj.w / n2, conj.x / n2, conj.y / n2, conj.z / n2);
  }

  List<double> rotateVector(List<double> v) {
    var qVec = Quaternion(0, v[0], v[1], v[2]);
    var res = this * qVec * inverse();
    return [res.x, res.y, res.z];
  }

  @override
  String toString() => '($w, $x, $y, $z)';
}

