void fn0(List<String> args) {

  if (args.length != 2) {
    print('Usage: dart modular_inverse.dart <a> <m>');
    return;
  }

  final a = BigInt.parse(args[0]);
  final m = BigInt.parse(args[1]);

  if (m <= BigInt.one) {
    print('Modulus must be greater than 1.');
    return;
  }

  BigInt u1 = BigInt.one,  u2 = BigInt.zero, u3 = a % m;
  BigInt v1 = BigInt.zero, v2 = BigInt.one,  v3 = m;

  while (v3 != BigInt.zero) {
    final q  = u3 ~/ v3;              
    final t1 = u1 - q * v1;
    final t2 = u2 - q * v2;
    final t3 = u3 - q * v3;

    u1 = v1;  u2 = v2;  u3 = v3;
    v1 = t1;  v2 = t2;  v3 = t3;
  }

  if (u3 != BigInt.one) {
    print('No modular inverse exists because gcd($a, $m) = $u3 ≠ 1.');
    return;
  }

  var inverse = u1 % m;
  if (inverse < BigInt.zero) inverse += m;

  print(inverse);
}

