extension IntExtensions on int {
  /// Returns true if the integer is even.
  bool get isEven => this % 2 == 0;

  /// Returns true if the integer is odd.
  bool get isOdd => !isEven;

  /// Square of the integer.
  int get squared => this * this;

  /// Runs [action] exactly `this` times, providing the current
  /// 0-based index on each iteration.
  void times(void Function(int index) action) {
    for (var i = 0; i < this; i++) {
      action(i);
    }
  }
}

extension StringExtensions on String {
  /// Capitalizes the first character and returns a new string.
  String capitalize() =>
      isEmpty ? this : '${this[0].toUpperCase()}${substring(1)}';

  /// Returns true if the string reads the same backward as forward.
  bool get isPalindrome => this == split('').reversed.join();
}

extension NumListExtensions on List<num> {
  /// Sum of all numeric elements in the list.
  num get sum => fold<num>(0, (prev, element) => prev + element);

  /// Average value of the elements in the list.
  double get average => isEmpty ? 0 : sum / length;
}

