List<int> fn0(List<int> shelfCodes) {
  final sorted = List<int>.from(shelfCodes);

  int digit(int code, int divisor) {
    return (code.abs() ~/ divisor) % 10;
  }

  sorted.sort((a, b) {
    final shelfA = digit(a, 1);
    final shelfB = digit(b, 1);
    final overflowA = shelfA == 0 ? 1 : 0;
    final overflowB = shelfB == 0 ? 1 : 0;
    if (overflowA != overflowB) return overflowA - overflowB;

    final roomA = digit(a, 1000);
    final roomB = digit(b, 1000);
    if (roomA != roomB) return roomA.compareTo(roomB);

    final aisleA = digit(a, 100);
    final aisleB = digit(b, 100);
    final oddGroupA = aisleA.isOdd ? 0 : 1;
    final oddGroupB = aisleB.isOdd ? 0 : 1;
    if (oddGroupA != oddGroupB) return oddGroupA - oddGroupB;
    if (aisleA != aisleB) {
      return oddGroupA == 0 ? aisleA.compareTo(aisleB) : aisleB.compareTo(aisleA);
    }

    final bayA = digit(a, 10);
    final bayB = digit(b, 10);
    if (bayA != bayB) return bayA.compareTo(bayB);
    if (shelfA != shelfB) return shelfB.compareTo(shelfA);
    return a.compareTo(b);
  });

  return sorted;
}

