double fn0(String instructions) {
  List<double> stack = [];
  for (int i = 0; i < instructions.length; i++) {
    String c = instructions[i];
    if (c == 'B') {
      if (stack.isNotEmpty) stack.removeLast();
    } else if (c == 'D') {
      if (stack.isNotEmpty) stack.add(stack.last);
    } else if (c == 'R') {
      for (int l = 0, r = stack.length - 1; l < r; l++, r--) {
        double temp = stack[l];
        stack[l] = stack[r];
        stack[r] = temp;
      }
    } else if (c == 'M' && stack.length >= 2) {
      double b = stack.removeLast();
      double a = stack.removeLast();
      stack.add((a + b) / 2.0);
    } else if (c == 'P' && stack.length >= 2) {
      double b = stack.removeLast();
      double a = stack.removeLast();
      stack.add(a * b);
    } else if (c == 'C' && stack.length >= 2) {
      double b = stack.removeLast();
      double a = stack.removeLast();
      stack.addAll(a == b ? [a * 2.0] : [a, b]);
    } else if (c == 'S' && stack.isNotEmpty) {
      double sum = 0.0;
      for (double v in stack) sum += v;
      stack.clear();
      stack.add(sum);
    } else {
      int code = c.codeUnitAt(0);
      if (code >= 48 && code <= 57) stack.add((code - 48).toDouble());
    }
  }
  if (stack.isEmpty) return 0.0;
  double total = 0.0;
  for (double v in stack) total += v;
  return total;
}

