  const binNames = ["excellent", "good", "fair", "poor", "unusable"];
  const binMins = [-50, -60, -70, -80, -100];

  int firstIndexLessThan(int threshold) {
    int low = 0;
    int high = signals.length;
    while (low < high) {
      int mid = (low + high) >> 1;
      if (signals[mid] < threshold) {
        high = mid;
      } else {
        low = mid + 1;
      }
    }
    return low;
  }

  List<int> starts = List.filled(binNames.length, 0);
  starts[0] = 0;
  for (int i = 1; i < binNames.length; i++) {
    starts[i] = firstIndexLessThan(binMins[i - 1]);
  }

  Map<String, int> result = {};
  for (int i = 0; i < binNames.length; i++) {
    int start = starts[i];
    int end = (i == binNames.length - 1) ? signals.length - 1 : starts[i + 1] - 1;
    int count = end - start + 1;
    if (count >= k && k > 0) {
      result[binNames[i]] = signals[start + k - 1];
    } else {
      result[binNames[i]] = -1;
    }
  }
  return result;
}

