void fn0() {

  final Map<int, Map<int, double>> graph = {
    0: {1: 4, 2: 1},
    1: {3: 1},
    2: {1: 2, 3: 5},
    3: {}
  };

  final int source = 0;

  final Map<int, double> distances = {};

  final Map<int, int?> previous = {};

  final Set<int> visited = {};

  for (var node in graph.keys) {
    distances[node] = double.infinity;
    previous[node] = null;
  }
  distances[source] = 0;

  while (visited.length < graph.length) {

    int? u;
    double minDist = double.infinity;
    for (var node in graph.keys) {
      if (!visited.contains(node) && distances[node]! < minDist) {
        minDist = distances[node]!;
        u = node;
      }
    }

    if (u == null) break;

    visited.add(u);

    for (var entry in graph[u]!.entries) {
      var v = entry.key;
      var weight = entry.value;
      if (!visited.contains(v)) {
        var alt = distances[u]! + weight;
        if (alt < distances[v]!) {
          distances[v] = alt;
          previous[v] = u;
        }
      }
    }
  }

  List<int> getPath(int target) {
    var path = <int>[];
    int? current = target;
    while (current != null) {
      path.insert(0, current);
      current = previous[current];
    }
    return path;
  }

  for (var node in graph.keys) {
    if (distances[node] == double.infinity) {
      print('Node $node is unreachable from source $source.');
    } else {
      var path = getPath(node);
      print(
        'Shortest path from $source to $node: '
        'distance = ${distances[node]}, path = $path'
      );
    }
  }
}

