String fn0(List<int> dailyMasks, int referenceMask) {
  const int mask24 = 0xFFFFFF;

  int rotateLeft24(int value, int shift) {
    value &= mask24;
    shift %= 24;
    if (shift == 0) {
      return value;
    }
    return ((value << shift) | (value >> (24 - shift))) & mask24;
  }

  int popcount(int value) {
    value &= mask24;
    int count = 0;
    while (value != 0) {
      value &= value - 1;
      count++;
    }
    return count;
  }

  int transitionCount(int value) {
    value &= mask24;
    int rotated = rotateLeft24(value, 1);
    return popcount(value ^ rotated);
  }

  if (dailyMasks.isEmpty) {
    return 'empty';
  }

  referenceMask &= mask24;
  List<String> parts = <String>[];

  for (int day = 0; day < dailyMasks.length; day++) {
    int current = dailyMasks[day] & mask24;
    int bestShift = 0;
    int bestDiff = 25;
    int bestTransitions = 100;

    for (int shift = 0; shift < 24; shift++) {
      int rotated = rotateLeft24(current, shift);
      int diff = popcount(rotated ^ referenceMask);
      int transitions = transitionCount(rotated);

      if (diff < bestDiff ||
          (diff == bestDiff && transitions < bestTransitions) ||
          (diff == bestDiff &&
              transitions == bestTransitions &&
              shift < bestShift)) {
        bestDiff = diff;
        bestTransitions = transitions;
        bestShift = shift;
      }
    }

    if (bestDiff == 0) {
      parts.add('D$day@$bestShift');
    } else {
      parts.add('D$day@$bestShift:$bestDiff');
    }
  }

  return parts.join(',');
}

