  BigInt fib(int k) {
    final cached = memo[k];
    if (cached != null) return cached;
    final value = fib(k - 1) + fib(k - 2);
    memo[k] = value;
    return value;
  }

  for (int i = 0; i <= n; i++) {
    print('F($i) = ${fib(i)}');
  }
}

