int fn0(List<int> trainMinutes, int windowSize) {
  if (trainMinutes.isEmpty || windowSize <= 0) return 0;
  final freq = <int, int>{};
  for (final m in trainMinutes) {
    freq[m] = (freq[m] ?? 0) + 1;
  }
  final sortedMinutes = freq.keys.toList()..sort();
  final counts = <int>[];
  for (final m in sortedMinutes) {
    counts.add(freq[m]!);
  }
  int total = 0;
  int right = 0;
  int windowSum = 0;
  for (int left = 0; left < sortedMinutes.length; left++) {
    if (right < left) {
      right = left;
      windowSum = 0;
    }
    while (right < sortedMinutes.length &&
        sortedMinutes[right] < sortedMinutes[left] + windowSize) {
      windowSum += counts[right];
      right++;
    }
    total += windowSum;
    windowSum -= counts[left];
  }
  return total;
}

