  print('Host system is ${isLittleEndian ? 'little-endian' : 'big-endian'}');

  int value = 0x12345678;

  List<int> littleEndianBytes = _intToBytes(value, Endian.little);
  print('Little-endian bytes: ${littleEndianBytes.map((b) => b.toRadixString(16).padLeft(2, '0')).join(' ')}');

  List<int> bigEndianBytes = _intToBytes(value, Endian.big);
  print('Big-endian bytes: ${bigEndianBytes.map((b) => b.toRadixString(16).padLeft(2, '0')).join(' ')}');

  int fromLittle = _bytesToInt(littleEndianBytes, Endian.little);
  print('Value from little-endian bytes: 0x${fromLittle.toRadixString(16)}');

  int fromBig = _bytesToInt(bigEndianBytes, Endian.big);
  print('Value from big-endian bytes: 0x${fromBig.toRadixString(16)}');

  List<int> swapped = _swapEndianness(littleEndianBytes);
  print('Swapped from little to big: ${swapped.map((b) => b.toRadixString(16).padLeft(2, '0')).join(' ')}');
}

bool _detectHostEndianness() {
  Uint8List bytes = Uint8List(2);
  ByteData byteData = ByteData.view(bytes.buffer);
  byteData.setUint16(0, 1, Endian.little); 

  return bytes[0] == 1;
}

List<int> _intToBytes(int value, Endian endian) {
  Uint8List bytes = Uint8List(4);
  ByteData byteData = ByteData.view(bytes.buffer);
  byteData.setInt32(0, value, endian);
  return bytes;
}

int _bytesToInt(List<int> bytes, Endian endian) {
  if (bytes.length != 4) throw ArgumentError('Must be 4 bytes');
  Uint8List uint8List = Uint8List.fromList(bytes);
  ByteData byteData = ByteData.view(uint8List.buffer);
  return byteData.getInt32(0, endian);
}

List<int> _swapEndianness(List<int> bytes) {
  if (bytes.length != 4) throw ArgumentError('Must be 4 bytes');
  return bytes.reversed.toList();
}

