@pragma('vm:never-inline')
@pragma('vm:entry-point')
int fn0(List<int> crateWeights, int maxItemsPerManifest) {
  int n = crateWeights.length;
  if (n == 0) {
    return 0;
  }

  List<int> dp = List<int>.filled(n + 1, 1 << 30);
  dp[0] = 0;

  for (int i = 1; i <= n; i++) {
    int currentMax = 0;
    int currentSum = 0;

    for (int size = 1; size <= maxItemsPerManifest && size <= i; size++) {
      int weight = crateWeights[i - size];
      if (weight > currentMax) {
        currentMax = weight;
      }

      currentSum += weight;
      int capacity = currentMax * size;
      int waste = capacity - currentSum;

      int fn0 = dp[i - size] + waste;
      if (fn0 < dp[i]) {
        dp[i] = fn0;
      }
    }
  }

  return dp[n];
}

