    {'Milk', 'Bread', 'Butter'},
    {'Bread', 'Butter'},
    {'Milk', 'Bread'},
    {'Milk', 'Butter'},
    {'Milk', 'Bread', 'Butter'},
    {'Bread'},
  ];

  double minSupport = 0.5; 
  int totalTransactions = transactions.length;
  int minSupportCount = (minSupport * totalTransactions).ceil();

  Map<Set<String>, int> itemSupport = {};
  for (var transaction in transactions) {
    for (var item in transaction) {
      Set<String> itemSet = {item};
      itemSupport[itemSet] = (itemSupport[itemSet] ?? 0) + 1;
    }
  }

  List<Set<String>> frequentItemsets = [];
  Map<int, List<Set<String>>> frequentBySize = {};
  List<Set<String>> prevFrequent = itemSupport.entries
      .where((entry) => entry.value >= minSupportCount)
      .map((entry) => entry.key)
      .toList();
  frequentItemsets.addAll(prevFrequent);
  frequentBySize[1] = prevFrequent;

  List<Set<String>> generateCandidates(List<Set<String>> prevFrequent, int k) {
    List<Set<String>> candidates = [];
    for (int i = 0; i < prevFrequent.length; i++) {
      for (int j = i + 1; j < prevFrequent.length; j++) {
        List<String> list1 = prevFrequent[i].toList()..sort();
        List<String> list2 = prevFrequent[j].toList()..sort();
        bool canJoin = true;
        for (int m = 0; m < k - 2; m++) {
          if (list1[m] != list2[m]) {
            canJoin = false;
            break;
          }
        }
        if (canJoin && list1[k - 2] != list2[k - 2]) {
          Set<String> newCandidate = Set.from(list1)..add(list2[k - 2]);
          candidates.add(newCandidate);
        }
      }
    }
    return candidates;
  }

  Map<Set<String>, int> countSupport(List<Set<String>> candidates, List<Set<String>> transactions) {
    Map<Set<String>, int> support = {};
    for (var fn0 in candidates) {
      support[fn0] = 0;
      for (var transaction in transactions) {
        if (transaction.containsAll(fn0)) {
          support[fn0] = support[fn0]! + 1;
        }
      }
    }
    return support;
  }

  int k = 2;
  while (prevFrequent.isNotEmpty) {
    List<Set<String>> candidates = generateCandidates(prevFrequent, k);
    Map<Set<String>, int> support = countSupport(candidates, transactions);
    prevFrequent = support.entries
        .where((entry) => entry.value >= minSupportCount)
        .map((entry) => entry.key)
        .toList();
    if (prevFrequent.isNotEmpty) {
      frequentItemsets.addAll(prevFrequent);
      frequentBySize[k] = prevFrequent;
    }
    k++;
  }

  double minConfidence = 0.7;
  List<String> rules = [];
  for (var itemset in frequentItemsets) {
    if (itemset.length < 2) continue;

    for (int i = 1; i < (1 << itemset.length) - 1; i++) { 
      Set<String> antecedent = {};
      Set<String> consequent = Set.from(itemset);
      List<String> items = itemset.toList();
      for (int j = 0; j < items.length; j++) {
        if ((i & (1 << j)) != 0) {
          antecedent.add(items[j]);
          consequent.remove(items[j]);
        }
      }
      if (antecedent.isEmpty || consequent.isEmpty) continue;

      int suppAntecedent = 0;
      int suppItemset = 0;
      for (var t in transactions) {
        if (t.containsAll(antecedent)) suppAntecedent++;
        if (t.containsAll(itemset)) suppItemset++;
      }
      double confidence = suppItemset / suppAntecedent;
      if (confidence >= minConfidence) {
        rules.add('${antecedent.join(", ")} => ${consequent.join(", ")} (support: ${suppItemset / totalTransactions}, confidence: $confidence)');
      }
    }
