List<int> fn0(List<int> visibility) {
  int n = visibility.length;
  if (n == 0) return [];
  if (n == 1) return [0];
  List<int> dp = List<int>.filled(n, 0);
  List<List<int>> prev = List<List<int>>.filled(n, []);
  dp[0] = visibility[0];
  prev[0] = [0];
  dp[1] = visibility[0] > visibility[1] ? visibility[0] : visibility[1];
  prev[1] = visibility[0] > visibility[1] ? [0] : [1];
  for (int i = 2; i < n; i++) {
    int skip = dp[i - 1];
    int take = dp[i - 2] + visibility[i];
    if (take > skip) {
      dp[i] = take;
      prev[i] = List<int>.from(prev[i - 2])..add(i);
    } else {
      dp[i] = skip;
      prev[i] = List<int>.from(prev[i - 1]);
    }
  }
  return prev[n - 1];
}

