          grid[r + 1][c] == '.' ||
          grid[r][c - 1] == '.' ||
          grid[r][c + 1] == '.';

      if (adjacent) {
        counts[cell] = (counts[cell] ?? 0) + 1;
      }
    }
  }
  return counts;
}

