bool fn0(List<int> readings, int minCycleDrop) {
  if (minCycleDrop <= 0) {
    return false;
  }

  if (readings.isEmpty) {
    return true;
  }

  List<int> compressed = <int>[];
  for (int value in readings) {
    if (value < 0 || value > 100) {
      return false;
    }

    if (compressed.isEmpty || compressed.last != value) {
      compressed.add(value);
    }
  }

  if (compressed.length < 2) {
    return true;
  }

  List<int> pendingRecoveryPeaks = <int>[];
  int peak = compressed.first;
  int trough = compressed.first;
  bool descending = false;

  for (int i = 1; i < compressed.length; i++) {
    int current = compressed[i];
    int previous = compressed[i - 1];

    if (current < previous) {
      descending = true;
      trough = current < trough ? current : trough;

      if (current > peak) {
        peak = current;
        trough = current;
      }
    } else {
      if (descending) {
        int drop = peak - trough;
        if (drop >= minCycleDrop) {
          pendingRecoveryPeaks.add(peak);
        }
      }

      descending = false;

      while (pendingRecoveryPeaks.isNotEmpty &&
          current >= pendingRecoveryPeaks.last) {
        pendingRecoveryPeaks.removeLast();
      }

      if (current >= peak) {
        peak = current;
        trough = current;
      }
    }

    if (!descending && current > peak) {
      peak = current;
      trough = current;
    }
  }

  if (descending && peak - trough >= minCycleDrop) {
    pendingRecoveryPeaks.add(peak);
  }

  return pendingRecoveryPeaks.isEmpty;
}

