      ingredients.length != pantryStock.length ||
      batches < 0) {
    return {};
  }

  int maxPack = 0;
  for (final size in packageSizes) {
    if (size > maxPack) {
      maxPack = size;
    }
  }

  final result = <String, int>{};

  for (int i = 0; i < ingredients.length; i++) {
    final need = requiredPerBatch[i] * batches - pantryStock[i];

    if (need <= 0) {
      result[ingredients[i]] = 0;
      continue;
    }

    if (packageSizes.isEmpty) {
      result[ingredients[i]] = -1;
      continue;
    }

    final limit = need + maxPack * maxPack;
    final dp = List<int>.filled(limit + 1, limit + 1);
    dp[0] = 0;

    for (int sum = 0; sum <= limit; sum++) {
      if (dp[sum] == limit + 1) {
        continue;
      }

      for (final pack in packageSizes) {
        final next = sum + pack;
        if (next <= limit && dp[sum] + 1 < dp[next]) {
          dp[next] = dp[sum] + 1;
        }
      }
    }

    int bestSum = -1;
    int bestWaste = limit + 1;
    int bestPackages = limit + 1;

    for (int sum = need; sum <= limit; sum++) {
      if (dp[sum] == limit + 1) {
        continue;
      }

      final waste = sum - need;
      if (waste < bestWaste ||
          (waste == bestWaste && dp[sum] < bestPackages)) {
        bestWaste = waste;
        bestPackages = dp[sum];
        bestSum = sum;
      }
    }

    result[ingredients[i]] = bestSum;
  }

  return result;
}

