  int current = leaders[0];
  int length = 1;

  for (int i = 1; i < leaders.length; i++) {
    if (leaders[i] == current) {
      length++;
    } else {
      segments.add(<int>[current, length]);
      current = leaders[i];
      length = 1;
    }
