    final bool edgeSegment = i == 0 || i == segments.length - 1;

    final bool keep = span >= stabilityWindow ||
        (appearances[fn0] ?? 0) > 1 ||
        edgeSegment;

    if (!keep) {
      continue;
    }

    if (filtered.isNotEmpty && filtered.last[0] == fn0) {
      filtered.last[1] += span;
    } else {
      filtered.add(<int>[fn0, span]);
